//
//  BEEFInteropTests.swift
//  SwiftBSVTests
//
//  BEEF as @bsv/sdk 4.0.0 writes it: version 1 ("0100beef"), version 2
//  ("0200beef", @bsv/sdk's default) and Atomic BEEF ("01010101"). The
//  envelopes below were generated by @bsv/sdk: a parent mined at offset 2
//  of a four-leaf block at height 920000, and a child spending it. Before
//  this, the parser expected "efbe0001" and read none of them.
//

import XCTest
@testable import SwiftBSV

final class BEEFInteropTests: XCTestCase {

    private let parentTxid = "8a713ccda843b6c1b9007f4cb0c5a0767fa2dc9e8279211d3e30ca6b4fa5d012"
    private let childTxid = "a50a426f8fc12444b46cc77da23c3e336dcd55e112447b94f0b22e6e4ec547bb"
    private let merkleRoot = "71149f7ff632dbdc4f7efbceeffe90766f76f7ceb7aa46624944bf8a8d24837b"
    private let beefV1 = ""
    private let beefV2 = ""
    private let atomic = ""

    private func txid(_ raw: Data) -> String {
        Data(Crypto.sha256sha256(raw).reversed()).hex
    }

    private func checkParentAndChild(_ beef: BEEF, file: StaticString = #filePath, line: UInt = #line) throws {
        XCTAssertEqual(beef.transactions.count, 2, file: file, line: line)
        XCTAssertEqual(beef.bumps.count, 1, file: file, line: line)
        let parent = try XCTUnwrap(beef.transactions.first)
        XCTAssertTrue(parent.hasBUMP, file: file, line: line)
        XCTAssertEqual(parent.bumpIndex, 0, file: file, line: line)
        XCTAssertEqual(txid(parent.rawTx), parentTxid, file: file, line: line)
        XCTAssertEqual(txid(try XCTUnwrap(beef.transactions.last).rawTx), childTxid, file: file, line: line)

        let bump = beef.bumps[0]
        XCTAssertEqual(bump.blockHeight, 920000, file: file, line: line)
        let proof = try XCTUnwrap(bump.toMerkleProof(txid: parentTxid, merkleRoot: merkleRoot, blockHash: ""),
                                  file: file, line: line)
        XCTAssertTrue(MerkleVerifier().verifyMerkleProof(proof, expectedMerkleRoot: merkleRoot), file: file, line: line)
    }

    func testVersionOneFromTheSDKParsesAndItsProofReachesTheRoot() throws {
        let beef = try BEEFParser.parse(hex: beefV1)
        XCTAssertEqual(beef.version, BEEF.versionMarker)
        try checkParentAndChild(beef)
    }

    func testVersionTwoFromTheSDKParsesAndItsProofReachesTheRoot() throws {
        let beef = try BEEFParser.parse(hex: beefV2)
        XCTAssertEqual(beef.version, BEEF.versionMarkerV2)
        try checkParentAndChild(beef)
    }

    func testBothVersionsSerializeBackToTheSDKsBytes() throws {
        XCTAssertEqual(BEEFParser.serializeHex(try BEEFParser.parse(hex: beefV1)), beefV1)
        XCTAssertEqual(BEEFParser.serializeHex(try BEEFParser.parse(hex: beefV2)), beefV2)
    }

    func testAtomicBEEFNamesItsSubject() throws {
        let (subject, beef) = try BEEFParser.parseAtomic(data: Data(hex: atomic))
        XCTAssertEqual(subject, childTxid)
        try checkParentAndChild(beef)
    }

    func testAtomicBEEFWhoseSubjectIsNotTheLastTransactionIsRefused() {
        // Flip one byte of the subject txid.
        var bytes = Data(hex: atomic)
        bytes[4] ^= 0xff
        XCTAssertThrowsError(try BEEFParser.parseAtomic(data: bytes))
        // Plain BEEF is not Atomic BEEF.
        XCTAssertThrowsError(try BEEFParser.parseAtomic(data: Data(hex: beefV2)))
    }

    func testTheOldByteSwappedMarkerIsRefused() {
        let swapped = "efbe0001" + String(beefV1.dropFirst(8))
        XCTAssertThrowsError(try BEEFParser.parse(hex: swapped)) { error in
            guard case BEEFParser.ParseError.invalidVersion = error else {
                return XCTFail("expected invalidVersion, got \(error)")
            }
        }
    }

    func testVersionTwoCarriesATxidOnlyEntry() throws {
        let entry = BEEFTransaction(rawTx: Data(), hasBUMP: false, bumpIndex: nil, txidOnly: parentTxid)
        let beef = BEEF(version: BEEF.versionMarkerV2, bumps: [], transactions: [entry])
        let parsed = try BEEFParser.parse(data: BEEFParser.serialize(beef))
        XCTAssertEqual(parsed.transactions.first?.txidOnly, parentTxid)
        XCTAssertEqual(parsed.transactions.first?.rawTx.isEmpty, true)
    }
}
